// LoadClosedByAccountingPeriods loads the member's ClosedByAccountingPeriods into the .R struct
func (o *Member) LoadClosedByAccountingPeriods(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.ClosedByAccountingPeriods = nil
	o.R.Loaded.ClosedByAccountingPeriods = false

	related, err := o.ClosedByAccountingPeriods(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.ClosedByMember = o
		rel.R.Loaded.ClosedByMember = true
	}

	o.R.ClosedByAccountingPeriods = related
	o.R.Loaded.ClosedByAccountingPeriods = true
	return nil
}

// LoadClosedByAccountingPeriods loads the member's ClosedByAccountingPeriods into the .R struct
func (os MemberSlice) LoadClosedByAccountingPeriods(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accountingPeriods, err := os.ClosedByAccountingPeriods(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ClosedByAccountingPeriods = nil
		o.R.Loaded.ClosedByAccountingPeriods = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	memberByKey := make(map[uuid.UUID][]*Member, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		memberByKey[o.ID] = append(memberByKey[o.ID], o)
	}

	for _, rel := range accountingPeriods {

		if !rel.ClosedBy.Valid {
			continue
		}

		owners, ok := memberByKey[rel.ClosedBy.V]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.ClosedByMember = o
			rel.R.Loaded.ClosedByMember = true

			o.R.ClosedByAccountingPeriods = append(o.R.ClosedByAccountingPeriods, rel)

		}
	}

	return nil
}

